// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        address before = c.owner();
        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        // General rule: a non-owner cannot change ownership — the call reverts
        // and `owner` stays unchanged. The mutant lets anyone succeed and
        // changes `owner` to newOwner.
        assertTrue(!ok && c.owner() == before);
    }
}
